  'content.thisPortalDefinesTheRequiredKnowledgeSystem': { th: "พอร์ทัลนี้กำหนดความรู้ที่จำเป็น ความเชี่ยวชาญในระบบ มาตรฐานการปฏิบัติงาน และข้อกำหนดด้านธรรมาภิบาลสำหรับพนักงานใหม่ทุกคนในช่วง 90 วันแรก", en: "This portal defines the required knowledge, system mastery, execution standards, and governance expectations for all new employees during their first 90 days." },
  'content.confirmationOfEmploymentIsBasedOnCompetency': { th: "การยืนยันการจ้างงานพิจารณาจากความสามารถ ความถูกต้องของเอกสาร วินัยในการใช้ระบบ และความตระหนักถึงความเสี่ยง", en: "Confirmation of employment is based on competency, documentation accuracy, system discipline, and risk awareness." },
  'content.searchOrganizationContent': { th: "ค้นหาเนื้อหาในองค์กร", en: "Search organization content" },
  'content.welcomeMessageFromOurCeo': { th: "สารต้อนรับจากท่านกรรมการผู้จัดการ", en: "Welcome Message from our CEO" },
  'content.weReThrilledToHaveYouOnboard': { th: "เรารู้สึกยินดีเป็นอย่างยิ่งที่คุณมาร่วมงานกับเรา เราเชื่อว่าทุกคนที่นี่มีส่วนร่วมต่อความสำเร็จของเรา และเรามุ่งมั่นที่จะช่วยให้คุณเติบโตก้าวหน้า มาร่วมกันสร้างสิ่งที่ยิ่งใหญ่ไปด้วยกัน", en: "We’re thrilled to have you onboard. We believe that every person here contributes to our success, and we’re committed to helping you thrive. Let’s build something great together." },
  'content.mrVoravithChavananand': { th: "นาย วรวิทย์ ชวนะนันท์", en: "Mr. Voravith Chavananand" },
