  'content.disciplineProtectsOurLiquidityReputationAndLong': { th: "วินัยช่วยปกป้องสภาพคล่อง ชื่อเสียง และความมั่นคงในระยะยาวของเรา", en: "Discipline protects our liquidity, reputation, and long-term stability." },
  'content.everyActionHasOperationalAndFinancialImpact': { th: "ทุกการกระทำส่งผลกระทบต่อการดำเนินงานและการเงิน เรารับผิดชอบต่อ:", en: "Every action has operational and financial impact. We take ownership of:" },
